/**
 * ball-summarizer — the floating ball's status, straight from the tool calls.
 *
 * Nothing here calls a model. The plugin does two things:
 *
 *  1. It makes every tool schema require a `ball_doing` field — one short line
 *     saying what the model is doing right now. The harness assembles the
 *     model-facing tool list through the `system-prompt/assemble` waterfall and
 *     logs that same list as the request header, so a plugin that rewrites the
 *     assembly rewrites what the model is offered and what the call carries.
 *     The requirement is structural, not a reminder the model can forget.
 *
 *  2. It watches committed session events and puts the current state on the
 *     ball's existing status channel (`POST /ball/state`, `ball_doing`):
 *     `think` + 思考中 while a step is being generated, `work` + the
 *     `ball_doing` of the tool call that is running, `work` + 读取输出 while the
 *     result comes back. One push per state change, deduplicated, and `done` →
 *     `idle` when the turn ends so the bubble folds away.
 *
 * Zero cost per step: no provider call, no tokens, no counting, no summaries.
 */

import { appendFileSync, mkdirSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';

/** Loader row id, for diagnostics. */
export const name = 'ball-summarizer';

/** The prompt service owns the assembly waterfall this plugin transforms. */
export const inject = ['systemPrompt'];

/** The field every tool call must carry. */
export const BALL_DOING_FIELD = 'ball_doing';

/** What the model is told the field is for. */
export const BALL_DOING_DESCRIPTION =
    '你现在在做什么：一句话（中文，20 字以内），会显示在用户的悬浮球上。每次调用工具都必须填，写具体动作。';

/** The zero-cost status lines that are not model-supplied. */
export const THINK_TEXT = '思考中';
export const READING_TEXT = '读取输出';
export const RUNNING_PREFIX = '正在执行 ';

/** Prompt section that states the requirement in words as well as in the schema. */
export const PROMPT_SECTION = 'ball:doing-field';
export const PROMPT_HINT =
    '调用任何工具时，参数里都必须带 `ball_doing`：一句话（中文，20 字以内）说明你现在在做什么。'
    + '它会直接显示在用户的悬浮球上，不需要另外汇报，也不要写工具名以外的套话。';

/**
 * Defaults for every config field; the row's `config` overrides them.
 *
 * No `Config` schema and no static `@deepseek-ai/*` import on purpose: a profile
 * bundle added as a symlinked local package is loaded from the workspace, and a
 * specifier the loader cannot resolve would fail the whole row at activation.
 * Every field therefore defaults here, and the module imports only `node:`.
 */
const DEFAULTS = {
    /** Schema field name and its model-facing description. */
    field: BALL_DOING_FIELD,
    description: BALL_DOING_DESCRIPTION,
    /** Add the field to `required` as well as `properties`. */
    required: true,
    /**
     * Also state the requirement in the system prompt.
     *
     * Measured on this deployment: the schema alone is not enough — the request
     * carried all 44 tools with `ball_doing` first in `properties` and in
     * `required`, and the next two tool calls still came back without it. The
     * declaration makes the field legal and expected; the section is what gets
     * it filled. `false` keeps the schema requirement alone.
     */
    promptHint: true,
    /** Status lines that come from events rather than from the model. */
    thinkingText: THINK_TEXT,
    readingText: READING_TEXT,
    /** When a call carries no field (or an empty one), say which tool runs. */
    fallbackToToolName: true,
    /** Re-say the current line on this cadence; the app folds a status away
     *  after 25 s without one. Never calls a model. */
    refreshMs: 18000,
    /**
     * How long a line must have been on the ball before a *work* line (a tool
     * call, 读取输出, `done`, `idle`) may replace it. Never shorter than this:
     * the user is reading what is running. A line that arrives inside the
     * window is held — newest only — and shown when the window ends.
     */
    minDwellMs: 500,
    /**
     * How long a line must have been on the ball before 思考中 may replace it.
     * Longer than the work window on purpose: the user gets time to finish
     * reading what was running before the bubble goes back to "thinking".
     */
    thinkHoldMs: 2000,
    heartbeatMaxMs: 1200000,
    /** A session with no event for this long is not "running" any more. */
    quietMs: 60000,
    includeSubagents: false,
    /** Also report the focused conversation’s sub-conversations (team members). */
    includeDescendants: true,
    /**
     * The title the client half pins on the floating ball's own conversation.
     * Such a session ends its turn with the model's own words on the ball
     * instead of a status line: the user reads one bubble from another app and
     * answers through the ball's input bar, so a question that lives only in the
     * transcript is one they cannot answer. `''` turns this off (every session
     * then keeps the plain turn-end `done` line).
     */
    ballTitle: '悬浮球',
    /** How much of that closing message fits: three wrapped bubble lines. */
    ballReplyChars: 180,
    dryRun: false,
    bridgeUrl: '',
    bridgeToken: '',
    logFile: '',
};

/** Same two values the `ball` CLI falls back to when the app passes no env. */
const BRIDGE_ENV_FILES = ['/etc/dsh-android/bridge.env'];

/** Flatten to one short line: the balloon shows a line, not a paragraph. */
export function oneLine(text, max = 40) {
    const flat = String(text == null ? '' : text)
        .replace(/[\r\n\t]+/g, ' ')
        .replace(/^[\s"'“”‘’「」《》]+|[\s"'“”‘’「」《》]+$/g, '')
        .replace(/\s{2,}/g, ' ')
        .trim();
    return flat.length > max ? flat.slice(0, max) : flat;
}

/**
 * Add the required status field to every tool schema in an assembly.
 *
 * This is the whole "every tool call must carry it" requirement: the assembly
 * this returns is what the agent loop logs as the request header and hands to
 * the provider, and the implicit parameter schema the harness builds sets no
 * `additionalProperties: false`, so the extra argument a model sends is
 * accepted by the tool's own validation and simply ignored by its body.
 *
 * Pure and idempotent: a tool that already declares the field is left alone, a
 * tool without an object parameter schema is left alone, and the input is never
 * mutated.
 *
 * @param tools - the assembly's tool declarations.
 * @param field - the property name to require.
 * @param description - what the model is told the property means.
 * @param required - whether to add the property to `required`.
 * @returns a new declaration list, with the field added where it applies.
 */
export function addBallDoingField(tools, field = BALL_DOING_FIELD, description = BALL_DOING_DESCRIPTION, required = true) {
    if (!Array.isArray(tools) || field === '') return tools;
    let added = 0;
    const next = tools.map((tool) => {
        const parameters = tool?.parameters;
        if (parameters === null || typeof parameters !== 'object' || Array.isArray(parameters)) return tool;
        if (parameters.type !== 'object' || parameters.properties === null || typeof parameters.properties !== 'object') return tool;
        if (Object.hasOwn(parameters.properties, field)) return tool;
        added += 1;
        const declared = Array.isArray(parameters.required) ? parameters.required : [];
        return {
            ...tool,
            parameters: {
                ...parameters,
                properties: { [field]: { type: 'string', description }, ...parameters.properties },
                ...required && !declared.includes(field) ? { required: [field, ...declared] } : {},
            },
        };
    });
    return added === 0 ? tools : next;
}

/**
 * Create the status engine over a host.
 *
 * The host is the seam this plugin needs from the harness, which is also what
 * makes the behaviour testable without a running harness:
 *
 *   host.push(body)      → POST the ball status (or a stand-in)
 *   host.log(entry)      → JSONL evidence line
 *   host.now()           → clock
 *
 * @param config - plugin config (defaults applied here).
 * @param host - the host seam above.
 * @returns the engine: event intake, status tick, and for tests `pending`.
 */
export function createEngine(config, host) {
    const cfg = { ...DEFAULTS, ...config };
    const now = host.now || (() => Date.now());
    /** Sessions currently known to the harness, in first-seen order. */
    const sessions = new Map();
    const state = {
        ops: 0, signals: 0, deduped: 0, held: 0, heldLine: null, pushes: 0, pushFailures: 0, heartbeats: 0,
        withBallDoing: 0, missingBallDoing: 0, schemaAssemblies: 0, schemaToolsAdded: 0,
        /** Which conversation the ball is bound to, and why. */
        focusId: null, focusVia: 'none', focusAt: 0, switches: 0, skippedNotFocused: 0,
        /** Monotonic tick stamped on each user message: two of them can share a
         *  millisecond, and a tie must never decide which conversation is on
         *  screen. */
        userTick: 0,
        /** What the ball is showing now, or null when nothing is running. Every
         *  push sets it; the heartbeat only ever re-says it. */
        displayed: null, lastPushAt: 0,
    };
    /** Pushes go out in order: a slow one must not let a newer line land first. */
    let pushChain = Promise.resolve();

    const log = (entry) => {
        try {
            host.log({ at: now(), ...entry });
        } catch {
            /* evidence logging must never break the feature */
        }
    };

    const stateOf = (session) => {
        let entry = sessions.get(session);
        if (entry) return entry;
        const header = session?.header ?? {};
        entry = {
            session,
            id: session?.id ?? String(session),
            parentId: typeof header.parentSession === 'string' ? header.parentSession : '',
            top: header.origin !== 'subagent' && (header.delegationDepth ?? 0) === 0,
            ops: 0, turnOpen: false, lastEventAt: 0, lastTool: '', lastUserAt: 0,
            lastLine: null,
            lastReply: '',
            /** The user-source title this session was last renamed to. */
            userTitle: '',
            /** Whether the "is this the ball's thread" evidence line went out. */
            ballNoted: false,
            heartbeatSince: 0, closedPending: false, idleAt: 0,
        };
        sessions.set(session, entry);
        // A long-lived harness can create sessions forever; the map is only a
        // window, so keep its oldest entries from accumulating.
        if (sessions.size > 64) sessions.delete(sessions.keys().next().value);
        return entry;
    };

    const byId = (id) => [...sessions.values()].find((entry) => entry.id === id);

    /** Whether `entry` is a descendant of the session with `ancestorId`. */
    function isDescendant(entry, ancestorId) {
        let cursor = entry;
        for (let depth = 0; cursor?.parentId && depth < 16; depth++) {
            if (cursor.parentId === ancestorId) return true;
            cursor = byId(cursor.parentId);
        }
        return false;
    }

    /**
     * Whether this session may ever write to the ball: a top-level conversation,
     * the one in focus, or a sub-conversation of it. A background teammate of
     * some other conversation is none of those and stays off the ball.
     */
    function eligible(entry) {
        if (entry.top || cfg.includeSubagents) return true;
        const focus = resolveFocus();
        return focus ? isDescendant(entry, focus.entry.id) : false;
    }

    /**
     * Which conversation the ball is allowed to report on.
     *
     * The harness has no host-side notion of "the session the user is looking
     * at": the Web client keeps that selection, the `session.follow` stream
     * carries no registry, and no Remote dispatch event names the viewed
     * session. So focus is derived from the one signal that is unambiguous —
     * the user typing. A `user/message` from a real user means that session is
     * on screen; nothing else promotes a session.
     *
     * With no such message yet (the plugin loaded mid-conversation), the
     * fallback serves the newest *top-level* session, and a subagent can never
     * take that place: a background teammate must not own the ball.
     *
     * @returns the focused entry and why it was chosen, or null.
     */
    function resolveFocus() {
        let typed = null;
        for (const entry of sessions.values()) {
            // A delegated prompt is a `user/message` inside the *teammate*’s own
            // session, so only a top-level session may be promoted this way.
            if (!entry.top || !entry.lastUserAt) continue;
            if (!typed || entry.lastUserAt > typed.lastUserAt) typed = entry;
        }
        if (typed) return { entry: typed, via: 'user-message' };
        let recent = null;
        for (const entry of sessions.values()) {
            if (!entry.top) continue;
            if (!entry.lastEventAt) continue;
            if (!recent || entry.lastEventAt > recent.lastEventAt) recent = entry;
        }
        return recent ? { entry: recent, via: 'fallback-top' } : null;
    }

    /** Whether `entry` is the focused session or one of its descendants. */
    function inFocus(entry) {
        const focus = resolveFocus();
        // Nothing is known yet (no typing, no top-level session): only a
        // top-level session may write, so a teammate can never own the ball.
        if (!focus) return entry.top || cfg.includeSubagents;
        if (entry === focus.entry) return true;
        if (!cfg.includeDescendants) return false;
        return isDescendant(entry, focus.entry.id);
    }

    /**
     * Follow the user when they change conversations.
     *
     * The line on the ball belongs to the previous conversation, so it may not
     * stay: the new focus either gets its own last line back (if it has one
     * recent enough to still be true) or the bubble folds away with `idle`.
     * Both go through the dwell gate like any other non-think line.
     */
    function followFocus() {
        const focus = resolveFocus();
        const id = focus?.entry.id ?? '';
        if (id === state.focusId) return;
        const from = state.focusId;
        state.focusId = id;
        state.focusVia = focus?.via ?? 'none';
        state.focusAt = now();
        state.switches += 1;
        log({ ev: 'focus-switch', from: from || null, to: id || null, via: state.focusVia });
        const displayed = state.displayed;
        if (!displayed) return;
        if (displayed.sessionId === id || inFocus(displayed.entry)) return;
        const previous = byId(displayed.sessionId);
        if (previous) previous.lastLine = { phase: displayed.phase, text: displayed.text };
        const next = focus?.entry?.lastLine;
        state.displayed = null;
        if (next && now() - (focus.entry.lastLineAt ?? 0) <= cfg.quietMs) {
            log({ ev: 'focus-switch-in', to: id, text: next.text });
            void enqueuePush(next.phase, next.text, 'focus-switch', focus.entry);
        } else {
            log({ ev: 'focus-switch-out', from: from || null });
            void enqueuePush('idle', '', 'focus-switch', null);
        }
    }

    /**
     * Put one line on the ball, in order, and remember it as "what is showing".
     *
     * `note` is the trigger, and it lands in the evidence log, so the raw log
     * says which event produced which line. A `done` or `idle` line clears the
     * memory: nothing may revive the bubble after it has folded away.
     */
    function enqueuePush(phase, text, note, entry) {
        if (phase === 'idle' || phase === 'done') state.displayed = null;
        else state.displayed = { phase, text, session: entry ?? null, sessionId: entry?.id ?? '', entry: entry ?? null, at: now() };
        // The closing tick starts when `done` actually reaches the ball — a
        // `done` held back by the dwell must not start its own countdown early.
        if (phase === 'done' && entry) entry.idleAt = now() + 4000;
        if (entry && phase !== 'done' && phase !== 'idle') {
            entry.lastLine = { phase, text };
            entry.lastLineAt = now();
        }
        pushChain = pushChain
            .then(() => push(phase, text, note))
            .catch(() => { /* push() never throws; this is belt and braces */ });
        return pushChain;
    }

    /**
     * Show a line, or hold the newest one for the minimum dwell.
     *
     * The wait depends on what is arriving: 思考中 waits for `thinkHoldMs`
     * (the user gets to finish reading what was running), anything else waits
     * for `minDwellMs` (a floor, never shorter). There is no exemption in either
     * direction — the window is decided by the incoming line alone.
     *
     * Holding never queues: only the newest held line is kept, so a burst inside
     * the window pushes once, when the window ends, and the lines in between are
     * dropped rather than replayed.
     *
     * @returns true when the line went out (or was already showing), false when
     *   it was held for the window.
     */
    /**
     * How long the line on the ball must have been showing before `phase` may
     * replace it: 思考中 waits for thinkHoldMs, every other line for minDwellMs.
     * 0 disables that window.
     */
    function dwellWindow(phase) {
        return phase === 'think' ? (cfg.thinkHoldMs ?? 2000) : (cfg.minDwellMs ?? 500);
    }

    function emit(phase, text, trigger, entry, max = 46) {
        const line = oneLine(text, max);
        if (!line && phase !== 'idle') return true;
        const displayed = state.displayed;
        if (displayed && displayed.phase === phase && displayed.text === line) {
            state.deduped += 1;
            if (state.heldLine && state.heldLine.phase === phase && state.heldLine.text === line) state.heldLine = null;
            log({ ev: 'signal-skipped', phase, text: line, trigger, reason: 'same-text' });
            return true;
        }
        const window = dwellWindow(phase);
        if (displayed && window > 0 && now() - displayed.at < window) {
            state.held += 1;
            state.heldLine = { phase, text: line, trigger, entry: entry ?? null, at: now() };
            log({ ev: 'signal-held', phase, text: line, trigger, waitMs: window - (now() - displayed.at) });
            return false;
        }
        state.heldLine = null;
        state.signals += 1;
        log({ ev: 'signal', phase, text: line, trigger });
        void enqueuePush(phase, line, trigger, entry ?? null);
        return true;
    }

    /**
     * Show whatever was held back, once the line before it has had its time.
     *
     * Only the newest held line is ever shown — a burst inside the window
     * collapses into one push, never a replay of each line in turn.
     */
    function flushPending() {
        const pending = state.heldLine;
        if (!pending) return;
        const displayed = state.displayed;
        const window = dwellWindow(pending.phase);
        if (displayed && window > 0 && now() - displayed.at < window) return;
        state.heldLine = null;
        if (displayed && displayed.phase === pending.phase && displayed.text === pending.text) {
            state.deduped += 1;
            return;
        }
        state.signals += 1;
        log({ ev: 'signal', phase: pending.phase, text: pending.text, trigger: pending.trigger, held: true });
        void enqueuePush(pending.phase, pending.text, pending.trigger, pending.entry);
    }

    /**
     * An event-driven status line: free and deduplicated.
     *
     * A tool call says which tool is running, a tool result says the output is
     * being read, a new step says the model is thinking. It never calls a model.
     */
    function signal(phase, text, trigger, entry) {
        try {
            if (entry && !inFocus(entry)) {
                // Counted per operation, so the audit line means "N tool calls
                // happened in a conversation the ball is not reporting on".
                if (trigger === 'tool/call') state.skippedNotFocused += 1;
                log({ ev: 'push-skipped', session: entry.id, reason: 'not-focused', focus: state.focusId, trigger });
                return;
            }
            if (!oneLine(text, 46)) return;
            emit(phase, text, trigger, entry);
        } catch (error) {
            log({ ev: 'signal-error', error: error && error.message ? error.message : String(error) });
        }
    }

    async function push(phase, text, note) {
        if (cfg.dryRun) {
            log({ ev: 'push-dry', phase, text, note: note ?? '' });
            return;
        }
        try {
            const result = await host.push({ phase, text, ball_doing: text });
            state.pushes += 1;
            state.lastPushAt = now();
            log({
                ev: 'push', phase, text, note: note ?? '', http: result?.http ?? null,
                session: state.displayed?.sessionId ?? null, focus: state.focusId, via: state.focusVia,
                state: result?.state ?? null,
            });
        } catch (error) {
            state.pushFailures += 1;
            log({ ev: 'push-error', phase, text, error: error && error.message ? error.message : String(error) });
        }
    }

    /** The field out of a tool call's raw arguments, if the model supplied one. */
    function readBallDoing(args, field = cfg.field) {
        let parsed = args;
        if (typeof args === 'string') {
            if (args.trim() === '') return '';
            try {
                parsed = JSON.parse(args);
            } catch {
                return '';
            }
        }
        if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return '';
        const value = parsed[field];
        return typeof value === 'string' ? oneLine(value, 40) : '';
    }

    /** The text blocks of one committed assistant message, flattened. */
    function assistantText(data) {
        const content = data?.message?.content;
        if (!Array.isArray(content)) return '';
        return content
            .filter((block) => block && block.type === 'text' && typeof block.text === 'string')
            .map((block) => block.text)
            .join(' ');
    }

    /**
     * Whether this session is the floating ball's own conversation.
     *
     * Two inputs. A `session/title` event whose source is the user is the
     * cheap, service-free one — the client half renames the thread right after
     * creating it, so a *new* ball session is recognised before its first
     * prompt. The host's projection read covers the other case: a thread whose
     * title event happened before this plugin loaded (the ball's conversation
     * usually predates the process).
     *
     * @param session - session object the harness passed with the event.
     * @param entry - that session's tracked state, which remembers the event.
     */
    function isBall(session, entry) {
        if (!cfg.ballTitle) return false;
        if (entry?.userTitle === cfg.ballTitle) return true;
        try {
            return host.sessionTitle?.(session) === cfg.ballTitle;
        } catch {
            return false;
        }
    }

    /** One evidence line per session: how (or whether) it was recognised. */
    function noteBall(session, entry, matched) {
        if (entry.ballNoted) return;
        entry.ballNoted = true;
        log({
            ev: 'ball-check', session: entry.id ?? '', matched,
            via: entry.userTitle === cfg.ballTitle ? 'title-event' : 'projection',
            userTitle: entry.userTitle || null,
        });
    }

    /** Put the model's closing words on the ball. False when there are none. */
    function showReply(entry) {
        const max = cfg.ballReplyChars ?? 180;
        const line = oneLine(entry.lastReply ?? '', max);
        if (!line) return false;
        entry.lastReply = '';
        // Longer than a status line on purpose: the bubble wraps to three lines,
        // and a question plus its numbered options has to fit in them.
        emit('work', line, 'turn-end-reply', entry, max);
        return true;
    }

    /** One committed session event. Synchronous: the agent loop must not wait. */
    function accept(session, event) {
        let entry;
        try {
            entry = stateOf(session);
            entry.lastEventAt = now();
            const type = event?.type;
            const data = event?.data ?? {};
            if (type === 'user/message' && data.source?.kind === 'user') {
                // The user typed here: this is the conversation on screen. A
                // counter, not a timestamp — see state.userTick.
                entry.lastUserAt = ++state.userTick;
                entry.lastReply = '';                    // a new question supersedes the old line
            }
            followFocus();

            if (type === 'session/title') {
                // The client half pins the ball's title with a user rename; that
                // event is how this plugin learns which thread is the ball's own.
                const title = data?.title;
                if (typeof title === 'string' && data?.source?.kind === 'user') entry.userTitle = title.trim();
                return;
            }
            if (type === 'turn/start') {
                entry.turnOpen = true;
                if (!entry.heartbeatSince) entry.heartbeatSince = now();
                signal('think', cfg.thinkingText, 'turn/start', entry);
                return;
            }
            if (type === 'step/start') {
                // A step is the model generating: this is the only state that
                // may say "thinking". A running tool never does.
                signal('think', cfg.thinkingText, 'step/start', entry);
                return;
            }
            if (type === 'assistant/message') {
                // Remembered per session, not pushed: at turn end the ball's own
                // conversation shows these words instead of the last tool line.
                const reply = assistantText(data);
                if (reply) entry.lastReply = reply;
                return;
            }
            if (type === 'turn/end') {
                entry.turnOpen = false;
                // The ball's conversation ends on the model's own words. The user
                // reads one bubble from another app and answers through the input
                // bar, so a question that only exists in the transcript is a
                // question they cannot answer. `work`, not `done`: `done` folds
                // away after 2.6 s, and this line has to stay until they reply.
                const ball = isBall(session, entry);
                noteBall(session, entry, ball);
                if (ball && showReply(entry)) return;
                if (state.displayed && state.displayed.session === entry) entry.closedPending = true;
                return;
            }
            if (type === 'tool/result') {
                // The result is being read back into the model. Setting
                // `readingText` to '' drops this line entirely.
                // A ball session keeps whatever it is showing: 读取输出 lands a
                // moment before the turn-end reply and would only flicker.
                if (cfg.readingText && !isBall(session, entry)) signal('work', cfg.readingText, 'tool/result', entry);
                return;
            }
            if (type !== 'tool/call') return;
            // Every operation is counted, including a background teammate's:
            // the count is how the focus rule is audited. Only the push is
            // gated, in signal().
            sessions.delete(session);
            sessions.set(session, entry);
            entry.ops += 1;
            state.ops += 1;

            const toolName = String(data.name ?? 'tool');
            entry.lastTool = toolName;
            const doing = readBallDoing(data.arguments);
            if (doing) state.withBallDoing += 1;
            else state.missingBallDoing += 1;
            log({ ev: 'op', session: entry.id, n: entry.ops, tool: toolName, ballDoing: doing || null });
            const text = doing || (cfg.fallbackToToolName ? `${RUNNING_PREFIX}${oneLine(toolName, 24)}` : '');
            signal('work', text, 'tool/call', entry);
        } catch (error) {
            // A listener that throws would surface inside the harness's event
            // dispatch: never let that happen.
            log({ ev: 'accept-error', error: String(error && error.message ? error.message : error) });
        }
    }

    /** Heartbeat and turn-end close-out: both are just re-saying a known line. */
    async function tick() {
        try {
            // A line held for the minimum dwell goes out here, as soon as its
            // window is over — one push, the newest line, never a replay.
            flushPending();
            const displayed = state.displayed;
            const entry = displayed?.session
                ?? [...sessions.values()].filter((candidate) => candidate.closedPending && !candidate.turnOpen).pop();
            if (entry && entry.closedPending && !entry.turnOpen) {
                entry.closedPending = false;
                const closing = displayed && displayed.session === entry ? displayed.text : '';
                // `done` is not think, so it waits out the window like any other
                // line; enqueuePush() starts the fold-away countdown once it
                // actually reaches the ball.
                if (closing) emit('done', closing, 'turn-end', entry);
            } else if (entry && displayed
                && (entry.turnOpen || now() - entry.lastEventAt <= cfg.quietMs)
                && now() - state.lastPushAt >= cfg.refreshMs
                && (!entry.heartbeatSince || now() - entry.heartbeatSince <= cfg.heartbeatMaxMs)) {
                // Keep-alive: re-say exactly what is showing, never a different
                // line, so the ball cannot flip-flop on its own.
                state.heartbeats += 1;
                await enqueuePush(displayed.phase, displayed.text, 'heartbeat', entry);
            }
            for (const candidate of sessions.values()) {
                if (!candidate.idleAt || now() < candidate.idleAt) continue;
                candidate.idleAt = 0;
                if (candidate.turnOpen) continue;
                emit('idle', '', 'turn-end-idle', null);
            }
        } catch (error) {
            log({ ev: 'tick-error', error: error && error.message ? error.message : String(error) });
        }
    }

    return {
        accept,
        tick,
        signal,
        emit,
        flushPending,
        resolveFocus,
        inFocus,
        followFocus,
        readBallDoing,
        state,
        sessions,
        /** Resolves when every queued push has settled — tests only. */
        pending: async () => { await pushChain; },
    };
}

/** The loopback control bridge address: plugin config first, then the app's env. */
export function resolveBridge(config) {
    const env = process.env;
    const url = config.bridgeUrl || env.DSH_ANDROID_BRIDGE_URL || readBridgeFile('DSH_ANDROID_BRIDGE_URL');
    const token = config.bridgeToken || env.DSH_ANDROID_BRIDGE_TOKEN || readBridgeFile('DSH_ANDROID_BRIDGE_TOKEN');
    return url && token ? { url: url.replace(/\/+$/u, ''), token } : null;
}

function readBridgeFile(key) {
    for (const file of BRIDGE_ENV_FILES) {
        try {
            const match = new RegExp(`^\\s*${key}\\s*=\\s*(.*)\\s*$`, 'm').exec(readFileSync(file, 'utf8'));
            if (match) return match[1].replace(/^["']|["']$/g, '');
        } catch {
            /* no such file: keep looking */
        }
    }
    return '';
}

/** JSONL evidence log under the harness home, one line per event. */
export function createLogFile(config) {
    const file = config.logFile
        || join(process.env.DSH_HOME || join(homedir(), '.dsh'), 'ball-summary', 'ball-summarizer.jsonl');
    return (entry) => {
        try {
            mkdirSync(dirname(file), { recursive: true });
            appendFileSync(file, JSON.stringify(entry) + '\n');
        } catch {
            /* an unwritable log is not worth failing over */
        }
    };
}

/**
 * Mount the status plugin in a profile.
 *
 * The `system-prompt/assemble` listener is the required-field half: it runs
 * outermost (`prepend`) and global, calls the rest of the chain, and returns the
 * assembly with every tool schema extended. The harness logs exactly this
 * assembly as the request header, so the field is required by the model's own
 * tool declarations — nothing here depends on a model remembering an
 * instruction.
 *
 * @param ctx - Cordis context of the bundle's row.
 * @param config - row config; every field defaults in DEFAULTS.
 */
export function apply(ctx, config) {
    const config2 = config ?? {};
    const log = createLogFile(config2);
    const field = config2.field ?? BALL_DOING_FIELD;
    const description = config2.description ?? BALL_DOING_DESCRIPTION;
    const required = config2.required ?? true;
    const host = {
        push: async (body) => {
            const bridge = resolveBridge(config2);
            if (!bridge) throw new Error('no bridge (DSH_ANDROID_BRIDGE_URL/TOKEN unset)');
            const response = await fetch(`${bridge.url}/ball/state`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-Dsh-Token': bridge.token },
                body: JSON.stringify(body),
                signal: AbortSignal.timeout(5000),
            });
            const text = await response.text();
            let parsed = null;
            try {
                parsed = JSON.parse(text);
            } catch {
                /* the status still went out, even if the answer was not JSON */
            }
            if (!response.ok) throw new Error(`bridge HTTP ${response.status}`);
            return { http: response.status, state: parsed?.state ?? null };
        },
        log,
        warn: (...args) => {
            try {
                ctx.logger?.warn?.(...args);
            } catch {
                /* logger is not worth a throw */
            }
        },
        now: () => Date.now(),
        /**
         * The session's current title, out of the title projection.
         *
         * Read, not tracked from `session/title` events: the ball's thread
         * usually predates this process, so the event that carries its title
         * was never delivered here. Absent service = no ball session, which
         * degrades to the old behaviour rather than throwing.
         */
        sessionTitle: (session) => {
            try {
                const title = ctx.sessionProjections?.stateOf?.(session, 'title');
                return typeof title === 'string' ? title.trim() : '';
            } catch {
                return '';
            }
        },
    };
    const engine = createEngine(config2, host);

    // Every tool schema, on every request the agent loop builds. Global and
    // outermost: the assembly this returns is the one the harness logs and the
    // provider receives.
    ctx.on('system-prompt/assemble', async (assembly, _context, next) => {
        const result = await next();
        try {
            const tools = result?.tools;
            const extended = addBallDoingField(tools, field, description, required);
            const added = extended === tools ? 0 : extended.length;
            engine.state.schemaAssemblies += 1;
            if (added) {
                engine.state.schemaToolsAdded = added;
                log({ ev: 'schema', tools: added, field, required });
            }
            return extended === tools ? result : { ...result, tools: extended };
        } catch (error) {
            log({ ev: 'schema-error', error: error && error.message ? error.message : String(error) });
            return result;
        }
    }, { global: true, prepend: true });

    ctx.on('session/created', (session) => {
        try {
            log({ ev: 'session-created', session: session?.id ?? '', top: session?.header?.origin !== 'subagent' });
        } catch {
            /* never throw from a listener */
        }
    });
    // The requirement in words, next to the one in the schema. Placed after the
    // deployment's own sections (WEB_SURFACE + 60) so it reads as the last word
    // on how to call a tool. A plugin contribution — no core prompt is touched.
    if (config2.promptHint ?? true) {
        try {
            let order = 10160;
            try {
                order = ctx.systemPrompt.getSectionOrder('WEB_SURFACE') + 60;
            } catch {
                /* order table moved: the fixed slot after the web surface stands in */
            }
            ctx.systemPrompt.section({
                name: PROMPT_SECTION,
                order,
                text: () => config2.promptText ?? PROMPT_HINT,
            });
            log({ ev: 'prompt-hint', section: PROMPT_SECTION, order });
        } catch (error) {
            log({ ev: 'prompt-hint-error', error: error && error.message ? error.message : String(error) });
        }
    }

    ctx.on('session/disposed', (session) => {
        try {
            engine.sessions.delete(session);
        } catch {
            /* never throw from a listener */
        }
    });
    ctx.on('session/event', (session, event) => {
        engine.accept(session, event);
    });

    // One timer, owned by this plugin's fiber: the keep-alive and the turn-end
    // close-out. Unloaded with the plugin, so nothing runs after HMR.
    ctx.effect(() => {
        const dwell = Math.min(config2.minDwellMs ?? 500, config2.thinkHoldMs ?? 2000);
        const period = Math.max(200, Math.min(1000, Math.floor((dwell || 600) / 3)));
        const timer = setInterval(() => {
            void engine.tick();
        }, period);
        return () => clearInterval(timer);
    }, 'ball-summarizer: heartbeat');

    log({ ev: 'start', field, required, pid: process.pid });
    try {
        ctx.logger?.info?.('ball-summarizer: 每个工具调用都要带 %s，状态直接推到悬浮球（不调用模型）', field);
    } catch {
        /* logging is best-effort */
    }
}
